options.afterRender:
const variable="doc_page";
let current=Math.max(Number(context.grafana.replaceVariables("${doc_page}"))||1,1);
const pages=Math.max(Number(context.grafana.replaceVariables("${doc_pages}"))||1,1);
const root=context.element.querySelector(".kb-page-jump");
if(!root||root.dataset.ready==="true")return;
root.dataset.ready="true";
const bar=document.createElement("div");
Object.assign(bar.style,{display:"flex",alignItems:"center",justifyContent:"flex-end",gap:"8px",height:"100%",padding:"0 10px",whiteSpace:"nowrap"});
const makeButton=(text,label)=>{const button=document.createElement("button");button.type="button";button.textContent=text;button.setAttribute("aria-label",label);Object.assign(button.style,{padding:"6px 10px",color:"inherit",background:"transparent",border:"1px solid #6b7280",borderRadius:"4px"});return button;};
const prev=makeButton("‹","文档失败上一页");
bar.append(prev);
const prefix=document.createElement("span");prefix.textContent="第";bar.append(prefix);
const input=document.createElement("input");input.type="number";input.min="1";input.max=String(pages);input.step="1";input.required=true;input.setAttribute("aria-label","文档失败跳转页码");Object.assign(input.style,{width:"64px",padding:"6px 8px",color:"inherit",background:"transparent",border:"1px solid #6b7280",borderRadius:"4px",textAlign:"center"});
input.addEventListener("pointerdown",(event)=>event.stopPropagation());
input.addEventListener("mousedown",(event)=>event.stopPropagation());
input.addEventListener("click",(event)=>{event.stopPropagation();input.focus();});
bar.append(input);
const total=document.createElement("span");total.textContent="/ "+pages+" 页";bar.append(total);
const next=makeButton("›","文档失败下一页");
bar.append(next);
const size=document.createElement("span");size.textContent="50 条/页";bar.append(size);
const update=()=>{input.value=String(current);prev.disabled=current<=1;next.disabled=current>=pages;for(const button of [prev,next]){button.style.cursor=button.disabled?"default":"pointer";button.style.opacity=button.disabled?"0.45":"1";}};
const setPage=(page)=>{current=Math.min(Math.max(page,1),pages);update();context.grafana.locationService.partial({["var-"+variable]:String(current)});};
prev.addEventListener("click",()=>setPage(current-1));
next.addEventListener("click",()=>setPage(current+1));
input.addEventListener("keydown",(event)=>{event.stopPropagation();if(event.key!=="Enter")return;event.preventDefault();const page=Number.parseInt(input.value,10);if(!Number.isInteger(page)||page<1||page>pages){input.value=String(current);context.grafana.notifyError(["页码无效","请输入 1 到 "+pages]);return;}setPage(page);});
update();
root.append(bar);

